body {
  background-color: #0d1b2a;
  color: white;
  font-family: 'Arial', sans-serif;
  padding: 20px;
}

/* Overlay styles for dramatic focus */
.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(0, 0, 0, 0.8);
  z-index: 10;
}

/* Floating square card */
.floating-card {
  position: absolute;
  z-index: 20;
  background-color: white;
  color: #0d1b2a;
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.6);
  padding: 30px;
  width: 360px;
  font-size: 1rem;
}

.floating-card h2 {
  font-size: 1.4rem;
  font-weight: bold;
  color: orange;
}

.floating-card p {
  margin-top: 10px;
  font-size: 1rem;
  line-height: 1.5;
}

/* Arrow pointing to the active input/button */
.arrow {
  position: absolute;
  width: 30px;
  height: 30px;
  background-color: white;
  z-index: 20;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.4);
  transform: rotate(45deg);
}

/* Highlight styles for focused areas */
.highlight {
  position: relative;
  z-index: 30;
  border: 3px solid orange;
  border-radius: 20px;
  animation: blink 1s infinite;
}

@keyframes blink {
  50% {
    opacity: 0.7;
  }
}

/* Form container */
.container {
  position: relative;
  background-color: white;
  color: #0d1b2a;
  border-radius: 20px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
  padding: 50px;
  margin-top: 120px;
  width: 90%;
  max-width: 450px;
}

.disabled {
  pointer-events: none;
  background-color: rgba(13, 27, 42, 0.5);
  color: rgba(255, 255, 255, 0.5);
}

body {
    font-family: Arial, sans-serif;
    background-color: #f2f2f2;
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
}

.container {
    background-color: #fff;
    padding: 20px;
    border-radius: 15px;
    box-shadow: 0px 0px 10px 0px rgba(0, 0, 0, 0.1);
    width: 300px;
}

h1 {
    text-align: center;
    margin-bottom: 20px;
}

form {
    display: flex;
    flex-direction: column;
    align-items: center;
}

label {
    margin-bottom: 10px;
}

input[type="file"] {
    padding: 10px;
    margin-bottom: 20px;
    border-radius: 10px;
    border: 2px solid #ccc;
    width: 100%;
    box-sizing: border-box;
}

input[type="submit"] {
    background-color: #4CAF50;
    color: white;
    padding: 10px 20px;
    border: none;
    border-radius: 10px;
    cursor: pointer;
}

input[type="submit"]:hover {
    background-color: #45a049;
}

body::-webkit-scrollbar {
  width: 8px;
}
body::-webkit-scrollbar-thumb {
  background-color: rgba(255, 127, 36, 0.8);
  border-radius: 8px;
}

